update orders
status = #{status}, checkout_Time = #{checkoutTime}, pay_status = #{payStatus}, cancel_Reason = #{cancelReason}, rejection_Reason = #{rejectionReason}, cancel_Time = #{cancelTime}, delivery_Status = #{deliveryStatus}, delivery_Time = #{deliveryTime},
where id = #{id}

mapper.select:
select * from orders

    and number like concat('%',#{number},'%')
    and phone like concat('%',#{phone},'%')
    and status = #{status}
    and order_time between #{beginTime} and #{endTime}
    and user_Id = #{userId}

order by order_time desc

select * from orders

    and number like concat('%',#{number},'%')
    and phone like concat('%',#{phone},'%')
    and status = #{status}
    and user_Id = #{userId}

order by order_time desc

select count(0) from orders

    order_time >= #{begin}
    and order_time <= #{end}
    and status = #{status}

select count(0) as number, name from orders left join order_detail on orders.id = order_detail.order_id
where status = #{status} and order_time between #{begin} and #{end}
group by name order by number desc limit #{rank};
